import { DatePipe } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IUserCashRequestFilterModel, IUserCashRequestModel, UserCashRequestFilterModel } from 'src/app/data/model/person/TeacherModel';
import { AdminService } from 'src/app/data/service/admin/admin.service';

@Component({
  selector: 'app-seller-cash-requests',
  templateUrl: './seller-cash-requests.component.html',
  styleUrls: ['./seller-cash-requests.component.scss']
})
export class SellerCashRequestsComponent implements OnInit {

  selectedCategory = 'unDone';
  requests: IUserCashRequestFilterModel;
  selected = false;
  selectedRequest: IUserCashRequestModel;

  constructor(
    private adminService: AdminService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private activatedRoute: ActivatedRoute,
    public datepipe: DatePipe,
    private router: Router
  ) { }

  ngOnInit(): void {

    let filter: IUserCashRequestFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;

      filter =
        new UserCashRequestFilterModel(page, take, title);

      this.requests = filter;

      this.getDate(this.selectedCategory);
    });
  }

  getTime(date: Date): string {

    return this.datepipe.transform(date, 'HH:mm:ss');
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.requests.startPage == null) {
      return;
    }
    if (this.requests.pageId > this.requests.startPage && +this.requests.pageId - 1 > 0) {
      this.setQueryParams(+this.requests.pageId - 1);
    }
  }

  goNextPage() {

    if (this.requests.endPage == null) {
      return;
    }
    if (this.requests.pageId < this.requests.endPage) {
      this.setQueryParams(+this.requests.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.router
      .navigate(
        ['SuperAdminPanel', 'SellerCashRequests'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.requests.takeEntity ? this.requests.takeEntity : null,
            title: this.requests.title ? this.requests.title : null
          }
        });
  }

  ionViewWillEnter() {

    this.getDate(this.selectedCategory);
  }

  onSelectRequest(index: number | string) {

    this.selectedRequest = this.requests.requests[+index];
    this.selected = true;
  }

  onBackClick() {

    this.selected = false;
  }

  onSetDone() {

    this.presentSetDoneConfirm();
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.delete();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentSetDoneConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به تایید هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'تایید',
          handler: () => {
            this.setDone();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentSetUnDoneConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به عدم تایید هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'عدم تایید',
          handler: () => {
            this.setUnDone();
          }
        }
      ]
    });

    await alert.present();
  }

  setDone() {

    SharedIonic.loading(this.loadingController);

    this.adminService.SetDoneSellerCashRequestById(this.selectedRequest.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
          this.getDate(this.selectedCategory);
          this.selected = false;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  setUnDone() {

    SharedIonic.loading(this.loadingController);

    this.adminService.SetUnDoneSellerCashRequestById(this.selectedRequest.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
          this.getDate(this.selectedCategory);
          this.selected = false;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onSetUnDone() {

    this.presentSetUnDoneConfirm();
  }

  delete() {

    SharedIonic.loading(this.loadingController);

    this.adminService.DeleteSellerCashRequestById(this.selectedRequest.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
          this.getDate(this.selectedCategory);
          this.selected = false;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onDelete() {

    this.presentAlertConfirm();
  }

  categoryChanged() {

    this.getDate(this.selectedCategory);
  }

  getDate(type: string) {

    SharedIonic.loading(this.loadingController);

    switch (type) {
      case 'all':
        this.adminService.GetAllSellerCashRequestsByFilter(this.requests).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.requests = res.data;
              this.onBackClick();
            } else if (res.status === GResponse.NotFoundStatus) {

            } else {
              SharedIonic.unSuccessToast(this.toastController);

            }
          },
          err => {

            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case 'unDone':
        this.adminService.GetAllUnDoneSellerCashRequestsByFilter(this.requests).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.requests = res.data;
              this.onBackClick();
            } else if (res.status === GResponse.NotFoundStatus) {

            } else {

              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {

            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case 'done':
        this.adminService.GetAllDoneSellerCashRequestsByFilter(this.requests).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.requests = res.data;
              this.onBackClick();
            } else if (res.status === GResponse.NotFoundStatus) {

            } else {

              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {

            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;

      default:
        this.adminService.GetAllSellerCashRequestsByFilter(this.requests).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.requests = res.data;
            } else {
              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
    }
  }
}
